#!/usr/bin/env python3
"""
FertiTerra: the nav bar and the five pages behind it, built to Hertility's structure.

Run from the Fertiterra repo root:   python3 apply_ft.py

  1. components/header.tsx             full-width dropdown sheet, links left, assessment
                                       card right with a lime button; Symptoms is their
                                       five items: Trying to conceive, Experiencing
                                       symptoms, Planning ahead, Perimenopausal, Just curious
  2. components/ft/sections.tsx        test-page sections with five stage cards
  3. components/ft/stage-page.tsx      one stage page, shared by all five routes
  4. app/test-kits/<stage>/page.tsx    five real routes, so no dropdown link can 404
  5. app/test-kits/page.tsx            hub rebuilt to their structure
  6. app/test-kits/hormone-fertility   sections appended BELOW your screening flow
  7. components/ft/symptom-sections.tsx + app/symptoms

Backups: <file>.bak-before-ft   Safe to run twice.
"""
import os, sys, shutil, base64, subprocess, tempfile

if not (os.path.exists("components/header.tsx") and os.path.exists("app/test-kits/page.tsx")):
    sys.exit("Run this from the Fertiterra repo root.")

def put(path, data):
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    if os.path.exists(path):
        shutil.copy(path, path + ".bak-before-ft")
    open(path, "w", encoding="utf-8").write(data)
    print("  wrote " + path)

def dec(s): return base64.b64decode(s).decode()

print("1/7 nav bar")
tmpdir = tempfile.mkdtemp()
tmp = os.path.join(tmpdir, "apply_nav.py")
open(tmp, "w", encoding="utf-8").write(dec(""))
r = subprocess.run([sys.executable, tmp], cwd=os.getcwd(), capture_output=True, text=True)
out = (r.stdout + r.stderr)
line = [l for l in r.stdout.strip().splitlines() if l.strip()]
print("  " + (line[-1] if line else ""))
if r.returncode != 0 and "Already applied" not in out:
    print(out); sys.exit("Nav step failed.")

print("2/7 sections")
put("components/ft/sections.tsx", dec(""))
print("3/7 stage page")
put("components/ft/stage-page.tsx", dec(""))
print("4/7 five routes")
for slug in ['trying-to-conceive', 'experiencing-symptoms', 'planning-ahead', 'perimenopausal', 'just-curious']:
    put("app/test-kits/" + slug + "/page.tsx", dec({"trying-to-conceive": "", "experiencing-symptoms": "", "planning-ahead": "", "perimenopausal": "", "just-curious": ""}[slug]))
print("5/7 test hub")
put("app/test-kits/page.tsx", dec(""))

print("6/7 test page sections")
TEST = os.path.join("app", "test-kits", "hormone-fertility", "page.tsx")
t = open(TEST, encoding="utf-8").read()
if "ft-sections" not in t:
    shutil.copy(TEST, TEST + ".bak-before-ft")
    lines = t.split("\n")
    last = max(i for i, l in enumerate(lines) if l.startswith("import "))
    lines.insert(last + 1, 'import { TestTierCards, StageCards, SupportTabs, HormonePanel, ConsultationBand, ComparisonTable, PartnerBand, FaqAccordion } from "@/components/ft/sections"')
    t = "\n".join(lines)
    block = """
        {/* ft-sections: Hertility-shaped sections, FertiTerra branding */}
        <TestTierCards />
        <StageCards />
        <HormonePanel />
        <ConsultationBand />
        <SupportTabs />
        <ComparisonTable />
        <PartnerBand />
        <FaqAccordion />
"""
    i = t.index("</main>")
    t = t[:i] + block + "      " + t[i:]
    for a, c in [("rose-500","[#1F3D33]"),("rose-600","[#1F3D33]"),("rose-400","[#1F3D33]"),("rose-50","[#E4EDE6]"),("rose-100","[#E4EDE6]")]:
        t = t.replace(a, c)
    open(TEST, "w", encoding="utf-8").write(t)
    print("  appended " + TEST)
else:
    print("  already applied")

print("7/7 symptoms")
SYMPG = os.path.join("app", "symptoms", "page.tsx")
put("components/ft/symptom-sections.tsx", dec(""))
s = open(SYMPG, encoding="utf-8").read()
if "ft-symptom" not in s:
    shutil.copy(SYMPG, SYMPG + ".bak-before-ft")
    lines = s.split("\n")
    last = max(i for i, l in enumerate(lines) if l.startswith("import "))
    lines.insert(last + 1, 'import { SymptomByline, SymptomsIntro, WhatIsImbalance, ImbalanceVsCondition, OtherSymptoms, WhatToDoNext, ManagingSymptoms, HowWeCanHelp } from "@/components/ft/symptom-sections"')
    s = "\n".join(lines)
    a = '<section className="mt-16">'
    j = s.index(a)
    s = s[:j] + "{/* ft-symptom: intro band */}\n        <SymptomByline />\n        <SymptomsIntro />\n\n        " + s[j:]
    tail2 = """
        {/* ft-symptom: explainer sections */}
        <WhatIsImbalance />
        <ImbalanceVsCondition />
        <OtherSymptoms />
        <WhatToDoNext />
        <ManagingSymptoms />
        <HowWeCanHelp />
"""
    k = s.index("</main>")
    s = s[:k] + tail2 + "      " + s[k:]
    open(SYMPG, "w", encoding="utf-8").write(s)
    print("  appended " + SYMPG)
else:
    print("  already applied")

print("")
print("Done. Open /test-kits and each of the five stage pages from the Symptoms dropdown.")
print("Prices: 485,000 RWF Advanced, 385,000 RWF Standard.")
